# rubik_solve_asm: optimal 2x2x2 cube solver, hand-written RV32I.
#
# int rubik_solve_asm(const char *state, char *out, size_t cap)
#                                   a0 = state, a1 = out, a2 = cap; result in a0
#
# RV32I and Zicsr only: no mul, div, rem, no floating point, no compressed
# instructions, no heap, no recursion. Tests: tests/trubik.c.
#
# The algorithm of rubik.c: iterative deepening A* with the pattern databases
# as heuristic, cut short by the table of the states within 5 moves and the
# table of the states at distance 11 (rubik_tables.S, generated by
# tools/gen_rubik_tables.c). Two differences make it faster than the C:
#
#   * a state keeps its orientations only as their rank, which a move
#     updates with one load from rubik_asm_o_move;
#   * the permutation rank of a node is computed once and serves both the
#     heuristic and the table lookup.
#
# The search is a loop over an explicit stack of 16-byte frames in .bss:
#
#   +0..6  cubie of each slot (p)
#   +8     orientation rank (halfword)
#   +12    move being tried at this level, saved while a child is searched
#   +13    first move of the face that may not follow (0, 3, 6; 9 = none)
#   +14    the same for the base frame of a pass, kept across passes
#
# Registers during the search, all callee-saved so the helpers can use the
# temporaries freely:
#
#   s0  current frame          s6   rubik_asm_o_move
#   s1  g, moves made          s7   move tried at this level / steps left
#   s2  threshold, then n      s8   forbidden face (first move of it)
#   s3  next threshold         s9   g of the base frame
#   s4  moves[]                s10  rubik_asm_o_pdb
#   s5  .Lmove_p               s11  rubik_asm_p_pdb

    .equ    CACHE5_N, 12224     # states within 5 moves
    .equ    D11_N, 2644         # states at distance 11
    .equ    CACHE_DEPTH, 5
    .equ    FRAME, 16

    .text

    .globl  rubik_solve_asm
    .type   rubik_solve_asm, @function
    .align  2
rubik_solve_asm:
    addi    sp, sp, -64
    sw      ra, 60(sp)
    sw      s0, 56(sp)
    sw      s1, 52(sp)
    sw      s2, 48(sp)
    sw      s3, 44(sp)
    sw      s4, 40(sp)
    sw      s5, 36(sp)
    sw      s6, 32(sp)
    sw      s7, 28(sp)
    sw      s8, 24(sp)
    sw      s9, 20(sp)
    sw      s10, 16(sp)
    sw      s11, 12(sp)
    sw      a1, 8(sp)           # out
    sw      a2, 4(sp)           # cap

    # parse
    mv      t0, a0
    addi    t1, a0, 14
1:
    lbu     t2, 0(t0)
    beqz    t2, .Linvalid
    addi    t0, t0, 1
    bne     t0, t1, 1b
    lbu     t2, 0(t0)
    bnez    t2, .Linvalid

    # cubies 1..7, each once; orientations 1..3, sum a multiple of 3
    la      s0, .Lframes
    li      t3, 0
    li      t4, 0               # o sum
    li      t5, 0               # o rank
    li      t6, 0               # i
    li      a3, 7
2:
    add     a4, a0, t6
    lbu     a5, 0(a4)
    addi    a5, a5, -49
    bgeu    a5, a3, .Linvalid
    li      a6, 1
    sll     a6, a6, a5
    and     a7, t3, a6
    bnez    a7, .Linvalid
    or      t3, t3, a6
    add     a7, s0, t6
    sb      a5, 0(a7)
    lbu     a5, 7(a4)
    addi    a5, a5, -49
    li      a6, 3
    bgeu    a5, a6, .Linvalid
    add     t4, t4, a5
    li      a6, 6
    beq     t6, a6, 3f          # the seventh o is implied
    slli    a7, t5, 1
    add     t5, t5, a7
    add     t5, t5, a5          # rank = rank * 3 + o
3:
    addi    t6, t6, 1
    bne     t6, a3, 2b
    li      a6, 3
4:
    bltu    t4, a6, 5f
    addi    t4, t4, -3
    j       4b
5:
    bnez    t4, .Linvalid
    sh      t5, 8(s0)

    la      s4, .Lmoves
    la      s5, .Lmove_p
    la      s6, rubik_asm_o_move
    la      s10, rubik_asm_o_pdb
    la      s11, rubik_asm_p_pdb

    # start state
    mv      a0, s0
    jal     .Lp_rank
    add     t0, s11, a0
    lbu     t1, 0(t0)           # p distance
    lhu     t2, 8(s0)
    add     t3, s10, t2
    lbu     t3, 0(t3)           # o distance
    bgeu    t1, t3, 1f
    mv      t1, t3
1:
    li      s2, 0
    beqz    t1, .Lformat        # h == 0, solved
    mv      s3, t1              # h
    mv      a1, t2
    jal     .Lfull_rank
    mv      s7, a0              # rank of the start state
    la      a1, rubik_asm_cache5
    li      a2, CACHE5_N
    li      a3, 7
    jal     .Llookup
    beqz    a0, 2f
    srli    s2, a0, 4
    andi    s2, s2, 7           # n = d
    li      s1, 0
    mv      s7, s2
    j       .Lunpack            # within 5 moves, follow the table

2:
    mv      a0, s7
    la      a1, rubik_asm_d11
    li      a2, D11_N
    li      a3, 4
    jal     .Llookup
    beqz    a0, 3f
    # distance 11, make the stored move, then search at threshold 11
    andi    a2, a0, 15
    sb      a2, 0(s4)
    mv      a0, s0
    addi    a1, s0, FRAME
    jal     .Lapply
    mv      a0, a2
    jal     .Lface3
    addi    s0, s0, FRAME
    sb      a0, 14(s0)
    li      s1, 1
    li      s9, 1
    li      s2, 11
    j       .Lpass

3:
    # not in a table
    li      s1, 0
    li      s9, 0
    li      t0, CACHE_DEPTH + 1
    mv      s2, s3
    bge     s2, t0, 4f
    mv      s2, t0
4:
    li      t0, 9
    sb      t0, 14(s0)

.Lpass:
    li      s3, 99
    li      s7, 0
    lbu     s8, 14(s0)
.Lloop:
    bne     s7, s8, 1f
    addi    s7, s7, 3           # skip the face last turned
1:
    li      t0, 9
    bgeu    s7, t0, .Lpop
    mv      a0, s0
    addi    a1, s0, FRAME
    mv      a2, s7
    jal     .Lapply
    addi    a0, s0, FRAME
    jal     .Lp_rank            # a0 = p rank of the child
    add     t0, s11, a0
    lbu     t1, 0(t0)
    lhu     t2, FRAME + 8(s0)   # o rank of the child
    add     t3, s10, t2
    lbu     t3, 0(t3)
    bgeu    t1, t3, 2f
    mv      t1, t3
2:
    addi    t4, s1, 1           # g + 1
    add     t5, t4, t1          # bound = g + 1 + h
    blt     s2, t5, .Lover
    add     t6, s4, s1
    sb      s7, 0(t6)           # moves[g] = m
    addi    t6, t4, CACHE_DEPTH
    blt     t6, s2, .Ldescend

    mv      a1, t2
    jal     .Lfull_rank
    la      a1, rubik_asm_cache5
    li      a2, CACHE5_N
    li      a3, 7
    jal     .Llookup
    beqz    a0, .Lmiss
    srli    t0, a0, 4
    andi    t0, t0, 7           # d
    addi    t1, s1, 1
    add     t1, t1, t0          # g + 1 + d
    beq     t1, s2, .Lhit
    bge     s2, t1, .Lnext
    bge     t1, s3, .Lnext
    mv      s3, t1
    j       .Lnext
.Lmiss:
    addi    t1, s1, CACHE_DEPTH + 2
    bge     s2, t1, .Ldescend
    bge     t1, s3, .Lnext
    mv      s3, t1
    j       .Lnext
.Lover:
    bge     t5, s3, .Lnext
    mv      s3, t5
.Lnext:
    addi    s7, s7, 1
    j       .Lloop

.Ldescend:
    sb      s7, 12(s0)
    sb      s8, 13(s0)
    mv      a0, s7
    jal     .Lface3
    addi    s0, s0, FRAME
    addi    s1, s1, 1
    mv      s8, a0
    li      s7, 0
    j       .Lloop

.Lpop:
    beq     s1, s9, .Lpass_fail
    addi    s0, s0, -FRAME
    addi    s1, s1, -1
    lbu     s7, 12(s0)
    lbu     s8, 13(s0)
    addi    s7, s7, 1
    j       .Lloop

.Lpass_fail:
    mv      s2, s3              # the smallest bound above the threshold
    j       .Lpass

.Lhit:
    # n = threshold; the child is t0 = d moves from solved
    addi    s0, s0, FRAME
    addi    s1, s1, 1
    mv      s7, t0

    # follow the table from frame s0: s7 moves into moves[s1..]
.Lunpack:
    beqz    s7, .Lformat
    mv      a0, s0
    jal     .Lp_rank
    lhu     a1, 8(s0)
    jal     .Lfull_rank
    la      a1, rubik_asm_cache5
    li      a2, CACHE5_N
    li      a3, 7
    jal     .Llookup
    andi    a2, a0, 15
    add     t0, s4, s1
    sb      a2, 0(t0)
    mv      a0, s0
    addi    a1, s0, FRAME
    jal     .Lapply
    addi    s0, s0, FRAME
    addi    s1, s1, 1
    addi    s7, s7, -1
    j       .Lunpack

    # write the s2 moves of moves[] as text
.Lformat:
    la      t0, .Lnames
    li      t1, 1               # bytes needed, the NUL included
    li      t2, 0
1:
    bge     t2, s2, 2f
    add     t3, s4, t2
    lbu     t3, 0(t3)
    slli    t3, t3, 1
    add     t3, t0, t3
    lbu     t4, 1(t3)
    snez    t4, t4
    addi    t1, t1, 1
    add     t1, t1, t4
    beqz    t2, 3f
    addi    t1, t1, 1           # the space
3:
    addi    t2, t2, 1
    j       1b
2:
    lw      a1, 8(sp)
    lw      a2, 4(sp)
    bgeu    a2, t1, 4f
    beqz    a2, 5f
    sb      zero, 0(a1)
5:
    li      a0, -2
    j       .Lreturn
4:
    li      t2, 0
    mv      t5, a1
6:
    bge     t2, s2, 7f
    beqz    t2, 8f
    li      t6, 32
    sb      t6, 0(t5)
    addi    t5, t5, 1
8:
    add     t3, s4, t2
    lbu     t3, 0(t3)
    slli    t3, t3, 1
    add     t3, t0, t3
    lbu     t4, 0(t3)
    sb      t4, 0(t5)
    addi    t5, t5, 1
    lbu     t4, 1(t3)
    beqz    t4, 9f
    sb      t4, 0(t5)
    addi    t5, t5, 1
9:
    addi    t2, t2, 1
    j       6b
7:
    sb      zero, 0(t5)
    mv      a0, s2
    j       .Lreturn

.Linvalid:
    li      a0, -1
.Lreturn:
    lw      ra, 60(sp)
    lw      s0, 56(sp)
    lw      s1, 52(sp)
    lw      s2, 48(sp)
    lw      s3, 44(sp)
    lw      s4, 40(sp)
    lw      s5, 36(sp)
    lw      s6, 32(sp)
    lw      s7, 28(sp)
    lw      s8, 24(sp)
    lw      s9, 20(sp)
    lw      s10, 16(sp)
    lw      s11, 12(sp)
    addi    sp, sp, 64
    ret

# leaves that use only temp and the args

# Frame a1 = frame a0 after move a2. Keeps a0 and a2; clobbers t0-t2.
.Lapply:
    slli    t0, a2, 3
    add     t0, s5, t0
    lbu     t1, 0(t0)
    add     t1, a0, t1
    lbu     t1, 0(t1)
    sb      t1, 0(a1)
    lbu     t1, 1(t0)
    add     t1, a0, t1
    lbu     t1, 0(t1)
    sb      t1, 1(a1)
    lbu     t1, 2(t0)
    add     t1, a0, t1
    lbu     t1, 0(t1)
    sb      t1, 2(a1)
    lbu     t1, 3(t0)
    add     t1, a0, t1
    lbu     t1, 0(t1)
    sb      t1, 3(a1)
    lbu     t1, 4(t0)
    add     t1, a0, t1
    lbu     t1, 0(t1)
    sb      t1, 4(a1)
    lbu     t1, 5(t0)
    add     t1, a0, t1
    lbu     t1, 0(t1)
    sb      t1, 5(a1)
    lbu     t1, 6(t0)
    add     t1, a0, t1
    lbu     t1, 0(t1)
    sb      t1, 6(a1)
    lhu     t1, 8(a0)
    slli    t2, t1, 3
    add     t1, t1, t2          # o * 9
    add     t1, t1, a2
    slli    t1, t1, 1
    add     t1, s6, t1
    lhu     t1, 0(t1)           # o_move[o][m]
    sh      t1, 8(a1)
    ret

# a0 = permutation rank of frame a0: the Lehmer code in the factorial base,
# ((((n0 * 6 + n1) * 5 + n2) * 4 + n3) * 3 + n4) * 2 + n5, with ni the number
# of later cubies smaller than cubie i. Clobbers t0-t6, a1, a2.
.Lp_rank:
    lbu     t0, 0(a0)
    lbu     t1, 1(a0)
    lbu     t2, 2(a0)
    lbu     t3, 3(a0)
    lbu     t4, 4(a0)
    lbu     t5, 5(a0)
    lbu     t6, 6(a0)
    sltu    a1, t1, t0          # n0
    sltu    a2, t2, t0
    add     a1, a1, a2
    sltu    a2, t3, t0
    add     a1, a1, a2
    sltu    a2, t4, t0
    add     a1, a1, a2
    sltu    a2, t5, t0
    add     a1, a1, a2
    sltu    a2, t6, t0
    add     a1, a1, a2
    slli    a2, a1, 1           # * 6
    slli    a1, a1, 2
    add     a1, a1, a2
    sltu    a2, t2, t1          # + n1
    add     a1, a1, a2
    sltu    a2, t3, t1
    add     a1, a1, a2
    sltu    a2, t4, t1
    add     a1, a1, a2
    sltu    a2, t5, t1
    add     a1, a1, a2
    sltu    a2, t6, t1
    add     a1, a1, a2
    slli    a2, a1, 2           # * 5
    add     a1, a1, a2
    sltu    a2, t3, t2          # + n2
    add     a1, a1, a2
    sltu    a2, t4, t2
    add     a1, a1, a2
    sltu    a2, t5, t2
    add     a1, a1, a2
    sltu    a2, t6, t2
    add     a1, a1, a2
    slli    a1, a1, 2           # * 4
    sltu    a2, t4, t3          # + n3
    add     a1, a1, a2
    sltu    a2, t5, t3
    add     a1, a1, a2
    sltu    a2, t6, t3
    add     a1, a1, a2
    slli    a2, a1, 1           # * 3
    add     a1, a1, a2
    sltu    a2, t5, t4          # + n4
    add     a1, a1, a2
    sltu    a2, t6, t4
    add     a1, a1, a2
    slli    a1, a1, 1           # * 2
    sltu    a2, t6, t5          # + n5
    add     a0, a1, a2
    ret

# a0 = a0 * 729 + a1, as (a0 * 27) * 27 with 27 = 32 - 4 - 1. Clobbers t0, t1.
.Lfull_rank:
    slli    t0, a0, 5
    slli    t1, a0, 2
    sub     t0, t0, t1
    sub     t0, t0, a0
    slli    a0, t0, 5
    slli    t1, t0, 2
    sub     a0, a0, t1
    sub     a0, a0, t0
    add     a0, a0, a1
    ret

# Binary search of the a2 entries at a1, sorted by entry >> a3, for rank a0.
# Returns the entry, or 0. Clobbers t0-t3, a2.
.Llookup:
    li      t0, 0               # lo
    addi    t1, a2, -1          # hi
1:
    blt     t1, t0, 3f
    add     t2, t0, t1
    srli    t2, t2, 1           # mid
    slli    t3, t2, 2
    add     t3, a1, t3
    lw      t3, 0(t3)
    srl     a2, t3, a3
    beq     a2, a0, 2f
    bltu    a2, a0, 4f
    addi    t1, t2, -1
    j       1b
4:
    addi    t0, t2, 1
    j       1b
2:
    mv      a0, t3
    ret
3:
    li      a0, 0
    ret

# a0 = first move of the face of move a0: 0, 3 or 6. Clobbers t0, t1.
.Lface3:
    sltiu   t0, a0, 3
    sltiu   t1, a0, 6
    add     t0, t0, t1          # 2, 1 or 0
    slli    t1, t0, 1
    add     t1, t1, t0
    li      a0, 6
    sub     a0, a0, t1
    ret
    .size   rubik_solve_asm, .-rubik_solve_asm

    .section .rodata
    .align  2
# Source slot of each destination slot, per move (R R2 R' B B2 B' D D2 D'),
# padded to 8 bytes.
.Lmove_p:
    .byte   1, 4, 2, 0, 3, 5, 6, 0
    .byte   4, 3, 2, 1, 0, 5, 6, 0
    .byte   3, 0, 2, 4, 1, 5, 6, 0
    .byte   0, 1, 2, 4, 5, 6, 3, 0
    .byte   0, 1, 2, 5, 6, 3, 4, 0
    .byte   0, 1, 2, 6, 3, 4, 5, 0
    .byte   0, 2, 5, 3, 1, 4, 6, 0
    .byte   0, 5, 4, 3, 2, 1, 6, 0
    .byte   0, 4, 1, 3, 5, 2, 6, 0
# Face letter and suffix (0 for none) of each move.
.Lnames:
    .byte   'R', 0, 'R', '2', 'R', 39
    .byte   'B', 0, 'B', '2', 'B', 39
    .byte   'D', 0, 'D', '2', 'D', 39

    .section .bss
    .align  2
.Lframes:
    .zero   16 * FRAME
.Lmoves:
    .zero   16
